      // has to complete and the source has to be released.
      const { promise: destroyed, resolve: onDestroyed } = Promise.withResolvers<boolean>();
      const { promise: disposed, resolve: onDisposed } = Promise.withResolvers<boolean>();

      t.app.use((event) => {
