      const timeout = <T>(value: T) => new Promise<T>((r) => setTimeout(() => r(value), 500));
      expect(await Promise.race([destroyed, timeout(false)])).toBe(true);
      expect(await Promise.race([disposed, timeout(false)])).toBe(true);
    },
  );

