  it("returned and thrown errors agree on errHeaders", async () => {
    t.app.use((event) => {
      handleCors(event, { origin: "*" });
    });
    t.app.get("/returned", () => new Response("no", { status: 401 }));
    t.app.get("/thrown", () => {
      throw new HTTPError({ status: 401 });
    });
    for (const path of ["/returned", "/thrown"]) {
