import { z } from "zod/v4";
import {
  assertBodySize,
  bodyLimit,
  defineJsonRpcHandler,
  defineValidatedHandler,
  HTTPError,
  onError,
  readBody,
} from "../src/index.ts";
import { createBodyTooLargeError, limitRequestBody } from "srvx/body-limit";
import { describeMatrix } from "./_setup.ts";

import type { Middleware } from "../src/index.ts";
import type { ServerRequest } from "srvx";

describeMatrix("body limit", (t, { describe, it, expect }) => {
  it("allows a body within the limit", async () => {
    t.app.post("/", async (event) => readBody(event), { middleware: [bodyLimit(1024)] });
    const res = await t.fetch("/", { method: "POST", body: JSON.stringify({ hello: "world" }) });
    expect(res.status).toBe(200);
    expect(await res.json()).toMatchObject({ hello: "world" });
  });

  it("rejects an oversized buffered body with 413", async () => {
    // With a real transport an honest `content-length` triggers the fail-fast
    // path; in-process it is caught as the body is read. Either way: 413.
    t.app.post("/", async (event) => readBody(event), { middleware: [bodyLimit(4)] });
    const res = await t.fetch("/", { method: "POST", body: "way over the limit" });
    expect(res.status).toBe(413);
  });

  it("rejects an oversized body read via readBody with 413", async () => {
    t.app.post("/", async (event) => readBody(event), { middleware: [bodyLimit(4)] });
    const res = await t.fetch("/", {
      method: "POST",
      body: streamOf(["chunk-one", "chunk-two", "chunk-three"]),
      // @ts-expect-error duplex is required for a streaming body
      duplex: "half",
    });
    expect(res.status).toBe(413);
  });

  it("maps an oversized body in a validated handler to 413 (not 400)", async () => {
    const handler = defineValidatedHandler({
      validate: { body: z.object({ value: z.string() }) },
      handler: async (event) => event.req.json(),
    });
    // The typed handler narrows the event; registering it on a base route is a
    // known variance gap, unrelated to what this test exercises.
    t.app.post("/validated", handler as unknown as () => unknown, {
      middleware: [bodyLimit(4)],
    });
    const res = await t.fetch("/validated", {
      method: "POST",
      body: streamOf(['{"value":"', "way more than four bytes", '"}']),
      // @ts-expect-error duplex is required for a streaming body
      duplex: "half",
    });
    expect(res.status).toBe(413);
  });

  it("maps an oversized body in a JSON-RPC handler to 413 (not a parse error)", async () => {
    t.app.post("/rpc", defineJsonRpcHandler({ methods: { echo: (params: unknown) => params } }), {
      middleware: [bodyLimit(4)],
    });
    const res = await t.fetch("/rpc", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: streamOf(['{"jsonrpc":"2.0","id":1,', '"method":"echo","params":[1,2,3]}']),
      // @ts-expect-error duplex is required for a streaming body
      duplex: "half",
    });
    expect(res.status).toBe(413);
  });

  // Real (socket-backed) transport only: an in-process `FormData` body is a lazy
  // undici stream that throws an unhandled "already closed" error when the
  // multipart parse is aborted mid-flight — an artifact of the in-memory source,
  // not of real requests.
  it.skipIf(t.target === "web")("maps an oversized formData read to 413 (not 400)", async () => {
    t.app.post("/upload", async (event) => {
      assertBodySize(event, 4);
      const form = await event.req.formData();
      return Object.fromEntries(form.entries());
    });
    const form = new FormData();
    form.append("field", "a value that is definitely longer than four bytes");
    const res = await t.fetch("/upload", { method: "POST", body: form });
    expect(res.status).toBe(413);
  });

  it("does not count a chunked body the handler never reads", async () => {
    t.app.post("/ignore", async () => "ok", { middleware: [bodyLimit(4)] });
    // A streamed body has no `content-length`, so nothing is enforced up-front;
    // enforcement is tied to consumption and the handler never reads it.
    const res = await t.fetch("/ignore", {
      method: "POST",
      body: streamOf(["far larger", "than four bytes"]),
      // @ts-expect-error duplex is required for a streaming body
      duplex: "half",
    });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("ok");
  });

  // Server-level `maxRequestBodySize` (srvx on Node/Deno) rejects body reads with srvx's own
  // `BodyTooLargeError`, which carries the `HTTPError` shape so h3 handles it as a 413 (#1548).
  describe("server-level limit (srvx BodyTooLargeError)", () => {
    it("is recognized as an HTTPError", () => {
      expect(HTTPError.isError(createBodyTooLargeError(4))).toBe(true);
    });

    it("renders a thrown error as a handled 413", async () => {
      t.app.post("/", () => {
        throw createBodyTooLargeError(4);
      });
      const res = await t.fetch("/", { method: "POST" });
      expect(res.status).toBe(413);
      expect(await res.json()).toMatchObject({
        status: 413,
        message: "Request body exceeds the maximum allowed size of 4 bytes.",
      });
      expect(t.errors).toHaveLength(1);
      expect(t.errors[0].unhandled).toBeFalsy();
    });

    it("rejects an oversized readBody with 413", async () => {
      t.app.post("/", async (event) => readBody(event), { middleware: [serverLimit(4)] });
      const res = await t.fetch("/", {
        method: "POST",
        body: streamOf(["chunk-one", "chunk-two"]),
        // @ts-expect-error duplex is required for a streaming body
        duplex: "half",
      });
      expect(res.status).toBe(413);
    });

    it("passes a handled 413 to onError middleware", async () => {
      let hookError: HTTPError | undefined;
      t.app.post("/", async (event) => readBody(event), {
        middleware: [
          onError((error) => {
            hookError = error;
          }),
          serverLimit(4),
        ],
      });
      const res = await t.fetch("/", {
        method: "POST",
        body: streamOf(["chunk-one", "chunk-two"]),
        // @ts-expect-error duplex is required for a streaming body
        duplex: "half",
      });
      expect(res.status).toBe(413);
      expect(hookError?.status).toBe(413);
      expect(hookError?.unhandled).toBeFalsy();
    });

    it("maps an oversized body in a validated handler to 413 (not 400)", async () => {
      const handler = defineValidatedHandler({
        validate: { body: z.object({ value: z.string() }) },
        handler: async (event) => event.req.json(),
      });
      t.app.post("/validated", handler as unknown as () => unknown, {
        middleware: [serverLimit(4)],
      });
      const res = await t.fetch("/validated", {
        method: "POST",
        body: streamOf(['{"value":"', "way more than four bytes", '"}']),
        // @ts-expect-error duplex is required for a streaming body
        duplex: "half",
      });
      expect(res.status).toBe(413);
    });

    it("maps an oversized body in a JSON-RPC handler to 413 (not a parse error)", async () => {
      t.app.post("/rpc", defineJsonRpcHandler({ methods: { echo: (params: unknown) => params } }), {
        middleware: [serverLimit(4)],
      });
      const res = await t.fetch("/rpc", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: streamOf(['{"jsonrpc":"2.0","id":1,', '"method":"echo","params":[1,2,3]}']),
        // @ts-expect-error duplex is required for a streaming body
        duplex: "half",
      });
      expect(res.status).toBe(413);
    });

    // Real transport only, see the `assertBodySize` formData test above.
    it.skipIf(t.target === "web")(
      "maps an oversized readBody formData to 413 (not 400)",
      async () => {
        t.app.post("/upload", async (event) => readBody(event, { type: "formData" }), {
          middleware: [serverLimit(4)],
        });
        const form = new FormData();
        form.append("field", "a value that is definitely longer than four bytes");
        const res = await t.fetch("/upload", { method: "POST", body: form });
        expect(res.status).toBe(413);
      },
    );
  });
});

// Mimics srvx's server-level `maxRequestBodySize`: limits the body with srvx's default error.
function serverLimit(limit: number): Middleware {
  return (event) => {
    (event as { req: ServerRequest }).req = limitRequestBody(event.req, limit);
  };
}

function streamOf(parts: string[]): ReadableStream<Uint8Array> {
  return new ReadableStream<string>({
    start(controller) {
      for (const part of parts) controller.enqueue(part);
      controller.close();
    },
  }).pipeThrough(new TextEncoderStream());
}

import { ReadableStream } from "node:stream/web";
import { vi } from "vitest";
import { HTTPError, iterable } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("iterable", (t, { it, expect, describe }) => {
  describe("iterable", () => {
    it("sends empty body for an empty iterator", async () => {
      t.app.use(() => iterable([]));
      const result = await t.fetch("/");
      expect(result.headers.get("content-length")).toBe(null);
      expect(await result.text()).toBe("");
    });

    it("concatenates iterated values", async () => {
      t.app.use(() => iterable(["a", "b", "c"]));
      const result = await t.fetch("/");
      expect(await result.text()).toBe("abc");
    });

    describe("iterable support", () => {
      const cases: [string, () => unknown][] = [
        ["Array", () => ["the-value"]],
        ["Set", () => new Set(["the-value"])],
        ["Map.keys()", () => new Map([["the-value", "unused"]]).keys()],
        ["Map.values()", () => new Map([["unused", "the-value"]]).values()],
        ["Iterator object", () => ({ next: () => ({ value: "the-value", done: true }) })],
        [
          "AsyncIterator object",
          () => ({
            next: () => Promise.resolve({ value: "the-value", done: true }),
          }),
        ],
        [
          "Generator (yield)",
          () =>
            (function* () {
              yield "the-value";
            })(),
        ],
        [
          "Generator (return)",
          () =>
            // eslint-disable-next-line require-yield
            (function* () {
              return "the-value" as unknown;
            })(),
        ],
        [
          "Generator (yield*)",
          () =>
            (function* () {
              yield* ["the-value"];
            })(),
        ],
        [
          "AsyncGenerator",
          () =>
            (async function* () {
              await Promise.resolve();
              yield "the-value";
            })(),
        ],
        [
          "ReadableStream (push-mode)",
          () =>
            new ReadableStream({
              start(controller) {
                controller.enqueue("the-value");
                controller.close();
              },
            }),
        ],
        [
          "ReadableStream (pull-mode)",
          () =>
            new ReadableStream({
              pull(controller) {
                controller.enqueue("the-value");
                controller.close();
              },
            }),
        ],
      ];

      for (const [type, makeIterable] of cases) {
        it(type, async () => {
          t.app.use(() => iterable(makeIterable() as any));
          const response = await t.fetch("/");
          expect(await response.text()).toBe("the-value");
        });
      }
    });

    describe("response status and headers", () => {
      it("keeps the status staged before the iterable is returned", async () => {
        t.app.use((event) => {
          event.res.status = 201;
          return iterable(["a"]);
        });
        const result = await t.fetch("/");
        expect(result.status).toBe(201);
        expect(await result.text()).toBe("a");
      });

      it("applies status and headers set while producing the first chunk", async () => {
        t.app.use((event) =>
          iterable(async function* () {
            await Promise.resolve();
            event.res.status = 201;
            event.res.headers.set("hello", "world");
            yield "a";
            yield "b";
          }),
        );
        const result = await t.fetch("/");
        expect(result.status).toBe(201);
        expect(result.headers.get("hello")).toBe("world");
        expect(await result.text()).toBe("ab");
      });

      it("ignores changes made after the first chunk", async () => {
        t.app.use((event) =>
          iterable(async function* () {
            yield "a";
            event.res.status = 201;
            yield "b";
          }),
        );
        const result = await t.fetch("/");
        expect(result.status).toBe(200);
        expect(await result.text()).toBe("ab");
      });

      it("renders an error response when the first chunk throws", async () => {
        t.app.use(() =>
          iterable(async function* () {
            throw new HTTPError({ status: 418, message: "nope" });
            // eslint-disable-next-line no-unreachable
            yield "a";
          }),
        );
        const result = await t.fetch("/");
        expect(result.status).toBe(418);
        expect((await result.json()).message).toBe("nope");
      });
    });

    describe("serializer argument", () => {
      it("is called for every value", async () => {
        const testIterable = [1, "2", { field: 3 }, null];
        const textEncoder = new TextEncoder();
        const serializer = vi.fn(() => textEncoder.encode("x"));
        t.app.use(() => iterable(testIterable, { serializer }));
        const response = await t.fetch("/");
        expect(await response.text()).toBe("x".repeat(testIterable.length));
        expect(serializer).toBeCalledTimes(4);
        for (const [i, obj] of testIterable.entries()) {
          expect.soft(serializer).toHaveBeenNthCalledWith(i + 1, obj);
        }
      });
    });
  });
});

import { readFile } from "node:fs/promises";
import { vi, beforeEach } from "vitest";
import { setCookie } from "../src/index.ts";
import { fetchWithEvent, proxy, proxyRequest } from "../src/utils/proxy.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("proxy", (t, { it, expect, describe }) => {
  const spy = vi.spyOn(console, "error");
  describe("", () => {
    describe("proxy()", () => {
      it("works", async () => {
        t.app.all("/hello", () => "hello");
        t.app.all("/", (event) => {
          return proxy(event, "/hello");
        });

        const result = await t.fetch("/");

        expect(await result.text()).toBe("hello");
      });

      it.runIf(t.target === "node")(
        "passes upstream redirects through to the client by default",
        async () => {
          t.app.all("/redirect", (event) => {
            event.res.headers.set("location", "https://example.test/moved");
            return new Response(null, {
              status: 302,
              headers: event.res.headers,
            });
          });
          // Proxy to an absolute URL so the external `fetch()` path is exercised.
          t.app.all("/", (event) => {
            return proxy(event, `${t.url}/redirect`);
          });

          const result = await t.fetch("/", { redirect: "manual" });

          // The 3xx response is passed through verbatim, not followed.
          expect(result.status).toBe(302);
          expect(result.headers.get("location")).toBe("https://example.test/moved");
        },
      );
    });

    describe("proxyRequest()", () => {
      it("can proxy request", async () => {
        t.app.all("/debug", async (event) => {
          const headers = Object.fromEntries(event.req.headers.entries());
          const body = await event.req.text();
          return {
            method: event.req.method,
            headers,
            body,
          };
        });

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            headers: [["x-custom1", "overridden"]],
            fetchOptions: {
              headers: new Headers({ "x-custom2": "overridden" }),
            },
          });
        });

        const result = await t
          .fetch("/", {
            method: "POST",
            body: "hello",
            headers: {
              "content-type": "text/custom",
              "X-Custom1": "user",
              "X-Custom2": "user",
              "X-Custom3": "user",
            },
          })
          .then((r) => r.json());

        const { headers, ...data } = result;
        expect(headers["content-type"]).toEqual("text/custom");

        expect(headers["x-custom1"]).toEqual("overridden");
        expect(headers["x-custom2"]).toEqual("overridden");
        expect(headers["x-custom3"]).toEqual("user");

        expect(data).toMatchInlineSnapshot(`
          {
            "body": "hello",
            "method": "POST",
          }
        `);
      });

      it("can proxy query request body", async () => {
        t.app.all("/debug", async (event) => {
          return {
            method: event.req.method,
            body: await event.req.text(),
          };
        });

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug");
        });

        const result = await t
          .fetch("/", {
            method: "QUERY",
            body: "query body",
            headers: {
              "content-type": "text/plain",
            },
          })
          .then((r) => r.json());

        expect(result).toMatchObject({
          method: "QUERY",
          body: "query body",
        });
      });

      it("forwards the body of a custom method (not just the payload allowlist)", async () => {
        t.app.all("/debug", async (event) => {
          return {
            method: event.req.method,
            body: await event.req.text(),
          };
        });

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug");
        });

        const result = await t
          .fetch("/", {
            method: "REPORT",
            body: "report body",
            headers: {
              "content-type": "text/plain",
            },
          })
          .then((r) => r.json());

        expect(result).toMatchObject({
          method: "REPORT",
          body: "report body",
        });
      });

      it("sets duplex when a stream body is supplied via fetchOptions on a GET event", async () => {
        t.app.all("/debug", async (event) => {
          return {
            method: event.req.method,
            body: await event.req.text(),
          };
        });

        t.app.all("/", (event) => {
          const body = new ReadableStream({
            start(controller) {
              controller.enqueue(new TextEncoder().encode("override body"));
              controller.close();
            },
          });
          // Incoming event is a GET (no body); the caller supplies a stream body
          // and overrides the method. `duplex` must be derived from this final
          // body or the underlying fetch/Request throws.
          return proxyRequest(event, "/debug", {
            fetchOptions: { method: "POST", body },
          });
        });

        const result = await t.fetch("/", { method: "GET" }).then((r) => r.json());

        expect(result).toMatchObject({
          method: "POST",
          body: "override body",
        });
      });

      it("fetchWithEvent forwards a stream body without throwing on duplex", async () => {
        t.app.all("/debug", async (event) => {
          return {
            method: event.req.method,
            body: await event.req.text(),
          };
        });

        t.app.all("/", async (event) => {
          const body = new ReadableStream({
            start(controller) {
              controller.enqueue(new TextEncoder().encode("stream body"));
              controller.close();
            },
          });
          const res = await fetchWithEvent(event, "/debug", { method: "POST", body });
          return res.json();
        });

        const result = await t.fetch("/", { method: "GET" }).then((r) => r.json());

        expect(result).toMatchObject({
          method: "POST",
          body: "stream body",
        });
      });

      // A leading separator run is an *authority* to the URL parser, so an
      // "internal" (`/`-prefixed) target must not be resolvable to a foreign
      // origin. `\` counts as a separator for special schemes too, and the
      // parser *removes* tab/LF/CR before parsing, so those can interleave a
      // run that only looks like a single leading slash.
      for (const target of [
        "//evil.com/x",
        String.raw`/\evil.com/x`,
        "///evil.com/x",
        "/\t/evil.com/x",
        "/\n/evil.com/x",
        "/\r/evil.com/x",
        "/\t\\evil.com/x",
      ]) {
        it(`keeps an internal proxy target on the app origin: ${JSON.stringify(target)}`, async () => {
          t.app.all("/**", (event) => ({
            origin: event.url.origin,
            pathname: event.url.pathname,
          }));

          t.app.all("/", async (event) => {
            const res = await proxy(event, target);
            // `proxy()` returns an `HTTPResponse`; read its body directly.
            return { outer: event.url.origin, sub: await new Response(res.body).json() };
          });

          const result = await t.fetch("/").then((r) => r.json());

          expect(result.sub.origin).toBe(result.outer);
          expect(result.sub.pathname).toBe("/evil.com/x");
        });
      }

      for (const target of ["//evil.com/x", "/\t/evil.com/x"]) {
        it(`keeps an internal fetchWithEvent target on the app origin: ${JSON.stringify(target)}`, async () => {
          t.app.all("/**", (event) => ({ origin: event.url.origin }));

          t.app.all("/", async (event) => {
            const res = await fetchWithEvent(event, target);
            return { outer: event.url.origin, sub: await res.json() };
          });

          const result = await t.fetch("/").then((r) => r.json());

          expect(result.sub.origin).toBe(result.outer);
        });
      }

      it("does not forward incoming accept-encoding header", async () => {
        t.app.all("/debug", (event) => {
          return { headers: Object.fromEntries(event.req.headers.entries()) };
        });

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug");
        });

        const result = await t
          .fetch("/", {
            headers: { "accept-encoding": "zstd, br, gzip" },
          })
          .then((r) => r.json());

        expect(result.headers["accept-encoding"]).toBeUndefined();
      });

      it("forwards the incoming accept header to the upstream", async () => {
        t.app.all("/debug", (event) => {
          return { accept: event.req.headers.get("accept") };
        });

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug");
        });

        const result = await t
          .fetch("/", {
            headers: { accept: "application/json" },
          })
          .then((r) => r.json());

        expect(result.accept).toBe("application/json");
      });

      it("does not forward headers listed in filterHeaders (case-insensitive)", async () => {
        t.app.all("/debug", (event) => {
          return { headers: Object.fromEntries(event.req.headers.entries()) };
        });

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            // Mixed-case option must still match the lowercased header name.
            filterHeaders: ["X-Custom"],
          });
        });

        const result = await t
          .fetch("/", {
            headers: { "x-custom": "secret", "x-keep": "kept" },
          })
          .then((r) => r.json());

        expect(result.headers["x-custom"]).toBeUndefined();
        expect(result.headers["x-keep"]).toBe("kept");
      });

      // Node's transport layer manages the `connection` header, so a custom
      // nomination only survives the round-trip on the web target.
      it.runIf(t.target === "web")(
        "does not forward request headers nominated by the incoming Connection header",
        async () => {
          t.app.all("/debug", (event) => {
            return { headers: Object.fromEntries(event.req.headers.entries()) };
          });
          t.app.all("/", (event) => proxyRequest(event, "/debug"));

          const result = await t
            .fetch("/", {
              headers: {
                connection: "x-internal-auth, keep-alive",
                "x-internal-auth": "secret",
                "x-keep": "kept",
              },
            })
            .then((r) => r.json());

          // RFC 9110 §7.6.1: fields nominated by `Connection` are hop-by-hop.
          expect(result.headers["x-internal-auth"]).toBeUndefined();
          expect(result.headers["x-keep"]).toBe("kept");
        },
      );

      it("does not forward proxy-authorization / proxy-connection by default", async () => {
        t.app.all("/debug", (event) => {
          return { headers: Object.fromEntries(event.req.headers.entries()) };
        });
        t.app.all("/", (event) => proxyRequest(event, "/debug"));

        const result = await t
          .fetch("/", {
